# ---------------------------------------------------------------------------
# Hardcoded AES-CBC-256 ciphertexts extracted from libPersonalCode.so.
# Each is an uppercase hex string (null-terminated ASCII in the original binary).
# Three pairs: each pair = (RSA public-key XML, RSA-encrypted blob).
# ---------------------------------------------------------------------------
_CT = {
    "CT_R1_KEY":  "",
    "CT_R1_BLOB": "",
    "CT_R2_KEY":  "",
    "CT_R2_BLOB": "",
    "CT_R3_KEY":  "",
    "CT_R3_BLOB": "",
}

# ---------------------------------------------------------------------------
# NEON helpers  (numpy uint8 arithmetic, wraps at 256)
# ---------------------------------------------------------------------------

def _u8(arr) -> np.ndarray:
    if isinstance(arr, (bytes, bytearray)):
        return np.frombuffer(arr, dtype=np.uint8).copy()
    return np.asarray(arr, dtype=np.uint8)

def _rd(key: str) -> np.ndarray:
    """Return a 16-byte numpy uint8 array from the hardcoded _RODATA table."""
    return np.frombuffer(_RODATA[key], dtype=np.uint8).copy()

def rot(v, n: int) -> np.ndarray:
    """Rotate each byte LEFT by n bits."""
    v = _u8(v)
    return ((v << n) | (v >> (8 - n))).astype(np.uint8)

def imm(val: int) -> np.ndarray:
    return np.full(16, val, dtype=np.uint8)

def bxor(a, b) -> np.ndarray:
    return (_u8(a) ^ _u8(b)).astype(np.uint8)

def badd(a, b) -> np.ndarray:
    return (a.astype(np.uint16) + _u8(b).astype(np.uint16)).astype(np.uint8)

def bsub(a, b) -> np.ndarray:
    return (a.astype(np.int16) - _u8(b).astype(np.int16)).astype(np.uint8)

def bneg(v) -> np.ndarray:
    return bsub(imm(0), v)

# ---------------------------------------------------------------------------
# SIMD blocks — each returns ASCII hex string (32 or 64 chars)
# ---------------------------------------------------------------------------

def _block0_aes_iv() -> str:
    """
    VA 0x1dce60..0x1dcf78 — derives AES IV #1.
    Verified output: '0192C58D36E47A589AF01928376428AA'
    """
    q4 = _rd("R_BABC0")   # 0x00..0x0f
    q5 = _rd("R_BABA0")   # 0x10..0x1f

    v0 = badd(_rd("R_1249E7"), _rd("R_BA6B0"))
    v1 = badd(_rd("R_1249F7"), _rd("R_BA920"))

    v2 = rot(v0, 2); v3 = rot(v1, 2)
    v1t = bxor(v2, q4); v2t = bxor(v3, q5)
    v1t = bsub(imm(0x91), v1t); v0t = bsub(imm(0x91), v2t)
    v1t = bxor(v1t, q4);        v0t = bxor(v0t, q5)

    v2 = rot(v1t, 7); v3 = rot(v0t, 7)
    v0t = bsub(q4, v2); v1t = bsub(q5, v3)
    v0t = bxor(v0t, q4); v1t = bxor(v1t, q5)
    v0t = badd(v0t, imm(7)); v1t = badd(v1t, imm(7))
    v0t = bxor(v0t, q4); v1t = bxor(v1t, q5)

    v2 = rot(v0t, 7); v3 = rot(v1t, 7)
    v1f = bsub(imm(0xfe), v2); v2f = bsub(imm(0xfe), v3)
    v1f = bxor(v1f, imm(0x3a)); v0f = bxor(v2f, imm(0x3a))
    v1f = badd(v1f, _rd("R_BA680")); v0f = badd(v0f, _rd("R_BA930"))
    v1f = bxor(v1f, _rd("R_BA7F0")); v0f = bxor(v0f, _rd("R_BA5C0"))

    return (bytes(v1f) + bytes(v0f)).decode('ascii')


def _block1_aes_key() -> str:
    """
    VA 0x1dcf80..0x1dd1e0 — derives AES KEY #1 (64 ASCII hex chars = 32 bytes).
    Verified output: '0001029836537892876377726A4E78E77F987CC321180281AABB019654321000'
    """
    q22 = _rd("R_BABC0")
    q23 = _rd("R_BABA0")
    q16 = _rd("R_BA5D0")
    q17 = _rd("R_BA7C0")
    q18 = _rd("R_BAB00")
    q19 = _rd("R_BAB60")
    q20 = _rd("R_BA800")
    q21 = _rd("R_BA710")

    # Block 1a
    v0m = imm(0x18)
    v1 = badd(_rd("R_124A08"), v0m)
    v2 = badd(_rd("R_124A18"), v0m)
    v3 = badd(_rd("R_124A28"), v0m)
    v0 = badd(_rd("R_124A38"), v0m)
    v1 = bxor(v1, q22); v2 = bxor(v2, q23)
    v3 = bxor(v3, q16); v0 = bxor(v0, q17)
    v1 = badd(v1, q18); v2 = badd(v2, q19)
    v3 = badd(v3, q20); v0 = badd(v0, q21)
    v1 = bxor(v1, q22); v2 = bxor(v2, q23)
    v3 = bxor(v3, q16); v0 = bxor(v0, q17)

    # Block 1b
    v1 = badd(v1, _rd("R_BAA60"))
    v2 = badd(v2, _rd("R_BA940"))
    v3 = badd(v3, _rd("R_BA6A0"))
    v0 = badd(v0, _rd("R_BAA70"))

    v7m = imm(0x1c); v4m = imm(0xfe)
    v1 = bxor(v1, v7m); v2 = bxor(v2, v7m)
    v3 = bxor(v3, v7m); v0 = bxor(v0, v7m)
    v1 = bsub(v4m, v1); v2 = bsub(v4m, v2)
    v3 = bsub(v4m, v3); v0 = bsub(v4m, v0)

    r4 = rot(v1, 7); r5 = rot(v2, 7); r6 = rot(v3, 7); r7 = rot(v0, 7)
    v0 = bneg(r4); v1 = bneg(r5); v2 = bneg(r6); v3 = bneg(r7)

    v4m = imm(0x97)
    v0 = bxor(v0, q22); v1 = bxor(v1, q23)
    v2 = bxor(v2, q16); v3 = bxor(v3, q17)
    v0 = badd(v0, q18); v1 = badd(v1, q19)
    v2 = badd(v2, q20); v3 = badd(v3, q21)
    v0 = bxor(v0, q22); v1 = bxor(v1, q23)
    v2 = bxor(v2, q16); v3 = bxor(v3, q17)
    v0 = badd(v0, v4m); v1 = badd(v1, v4m)
    v2 = badd(v2, v4m); v3 = badd(v3, v4m)

    r4 = rot(v0, 1); r5 = rot(v1, 1); r6 = rot(v2, 1); r7 = rot(v3, 1)

    q730 = _rd("R_BA730"); qa10 = _rd("R_BAA10")
    qb70 = _rd("R_BAB70"); q890 = _rd("R_BA890")

    v0n = bsub(q730, r4); v2n = bsub(qa10, r5)
    v3n = bsub(qb70, r6); v4n = bsub(q890, r7)

    xb6 = imm(0xb6)
    v0n = bxor(v0n, xb6); v2n = bxor(v2n, xb6)
    v3n = bxor(v3n, xb6); v1n = bxor(v4n, xb6)

    v0n = badd(v0n, q18); v2n = badd(v2n, q19)
    v3n = badd(v3n, q20); v1n = badd(v1n, q21)

    r4 = rot(v0n, 7); r5 = rot(v2n, 7); r6 = rot(v3n, 7); r0 = rot(v1n, 7)

    v2f = badd(r4, imm(1)); v3f = badd(r5, imm(1))
    v4f = badd(r6, imm(1)); v0f = badd(r0, imm(1))

    v1_out = rot(v2f, 6); v5_out = rot(v3f, 6)
    v6_out = rot(v4f, 6); v2_out = rot(v0f, 6)

    return (bytes(v1_out) + bytes(v5_out) + bytes(v6_out) + bytes(v2_out)).decode('ascii')


def _block2_aes_iv() -> str:
    """
    VA 0x1dd328..0x1dd48c — derives AES IV #2 (32 ASCII hex chars = 16 bytes).
    """
    q22 = _rd("R_BABC0")
    q23 = _rd("R_BABA0")
    sp_a0 = _rd("R_BAB60")
    sp_b0 = _rd("R_BAB00")

    v4s = q22.copy(); v5s = q23.copy()
    v6 = imm(1)

    v0 = bxor(_rd("R_124A49"), imm(0x34))
    v1 = bxor(_rd("R_124A59"), imm(0x34))
    v0 = badd(v0, q22); v1 = badd(v1, q23)

    v2 = rot(v0, 5); v3 = rot(v1, 5)
    v1 = bxor(v2, imm(0x71)); v0 = bxor(v3, imm(0x71))
    v1 = badd(v1, v6); v0 = badd(v0, v6)

    v2 = rot(v1, 1); v3 = rot(v0, 1)
    v1 = bsub(imm(0x31), v2); v0 = bsub(imm(0x31), v3)
    v1 = bxor(v1, v4s); v0 = bxor(v0, v5s)
    v1 = badd(v1, imm(0x57)); v0 = badd(v0, imm(0x57))

    v2 = rot(v1, 6); v3 = rot(v0, 6)
    v0 = badd(v2, sp_b0); v1 = badd(v3, sp_a0)

    v2 = rot(v0, 7); v3 = rot(v1, 7)
    v2 = badd(v2, imm(0x3f)); v0 = badd(v3, imm(0x3f))
    v2 = bxor(v2, imm(0xaf)); v0 = bxor(v0, imm(0xaf))
    v2 = badd(v2, imm(0xc8)); v0 = badd(v0, imm(0xc8))
    v2 = bxor(v2, imm(0xad)); v0 = bxor(v0, imm(0xad))
    v2 = bsub(imm(0xe2), v2); v0 = bsub(imm(0xe2), v0)
    v2 = bxor(v2, imm(0xda)); v0 = bxor(v0, imm(0xda))

    v1 = rot(v2, 1); v3 = rot(v0, 1)
    v1 = badd(v1, v4s); v2 = badd(v3, v5s)
    v1 = bxor(v1, imm(0x13)); v0 = bxor(v2, imm(0x13))
    v1 = badd(v1, v6); v0 = badd(v0, v6)

    v2 = rot(v1, 1); v3 = rot(v0, 1)
    v1 = bsub(imm(0xd3), v2); v0 = bsub(imm(0xd3), v3)

    return (bytes(v1) + bytes(v0)).decode('ascii')


def _block3_aes_key() -> str:
    """
    VA 0x1dd498..0x1dd66c — derives AES KEY #2 (64 ASCII hex chars).
    """
    sp_c0 = _rd("R_BABA0")
    sp_d0 = _rd("R_BABC0")
    q18s  = _rd("R_BA7C0")
    q17s  = _rd("R_BA5D0")
    v19   = sp_d0.copy()

    b0 = _rd("R_124A6A"); b1 = _rd("R_124A7A")
    b2 = _rd("R_124A8A"); b3 = _rd("R_124A9A")

    v5b = imm(7)
    v0m = imm(0x88)

    v1 = badd(b0, v5b); v2 = badd(b1, v5b)
    v3 = badd(b2, v5b); v4 = badd(b3, v5b)
    v1 = bxor(v1, v0m); v2 = bxor(v2, v0m)
    v3 = bxor(v3, v0m); v0 = bxor(v4, v0m)
    v1 = badd(v1, imm(1)); v2 = badd(v2, imm(1))
    v3 = badd(v3, imm(1)); v0 = badd(v0, imm(1))

    r4 = rot(v1, 5); r5 = rot(v2, 5); r6 = rot(v3, 5); r7 = rot(v0, 5)

    v0 = bsub(sp_d0, r4); v1 = bsub(sp_c0, r5)
    v2 = bsub(q17s,  r6); v3 = bsub(q18s,  r7)

    q4_b3 = _rd("R_BAAB0"); q5_b3 = _rd("R_BAA80")
    q6_b3 = _rd("R_BA820"); q16_b3 = _rd("R_BA720")

    v0 = bxor(v0, sp_d0); v1 = bxor(v1, sp_c0)
    v2 = bxor(v2, q17s);  v3 = bxor(v3, q18s)
    v0 = badd(v0, q4_b3); v1 = badd(v1, q5_b3)
    v2 = badd(v2, q6_b3); v3 = badd(v3, q16_b3)
    v0 = bxor(v0, imm(0x89)); v1 = bxor(v1, imm(0x89))
    v2 = bxor(v2, imm(0x89)); v3 = bxor(v3, imm(0x89))

    v4t = imm(0x18)
    v0 = bsub(v4t, v0); v1 = bsub(v4t, v1)
    v2 = bsub(v4t, v2); v3 = bsub(v4t, v3)

    r4 = rot(v0, 7); r5 = rot(v1, 7); r6 = rot(v2, 7); r7 = rot(v3, 7)
    v1 = badd(r4, imm(0x4f)); v2 = badd(r5, imm(0x4f))
    v3 = badd(r6, imm(0x4f)); v0 = badd(r7, imm(0x4f))

    r4 = rot(v1, 5); r5 = rot(v2, 5); r6 = rot(v3, 5); r7 = rot(v0, 5)

    sp_60 = _rd("R_BA710"); sp_70 = _rd("R_BA800")
    sp_a0b = _rd("R_BAB60"); sp_b0b = _rd("R_BAB00")

    v0 = badd(r4, sp_b0b); v1 = badd(r5, sp_a0b)
    v2 = badd(r6, sp_70);  v3 = badd(r7, sp_60)

    v0 = bxor(v0, v19);  v1 = bxor(v1, sp_c0)
    v2 = bxor(v2, q17s); v3 = bxor(v3, q18s)
    v0 = badd(v0, v19);  v1 = badd(v1, sp_c0)
    v2 = badd(v2, q17s); v3 = badd(v3, q18s)
    v0 = bxor(v0, imm(0x6d)); v1 = bxor(v1, imm(0x6d))
    v2 = bxor(v2, imm(0x6d)); v3 = bxor(v3, imm(0x6d))
    v0 = badd(v0, imm(0xde)); v1 = badd(v1, imm(0xde))
    v2 = badd(v2, imm(0xde)); v3 = badd(v3, imm(0xde))
    v0 = bxor(v0, imm(0xc6)); v1 = bxor(v1, imm(0xc6))
    v2 = bxor(v2, imm(0xc6)); v3 = bxor(v3, imm(0xc6))

    return (bytes(v0) + bytes(v1) + bytes(v2) + bytes(v3)).decode('ascii')


def _block4_aes_iv() -> str:
    """
    VA 0x1dd864..0x1dd9a4 — derives AES IV #3 (32 ASCII hex chars).
    """
    sp_c0 = _rd("R_BABA0")
    sp_d0 = _rd("R_BABC0")
    v4s = sp_d0.copy(); v5s = sp_c0.copy()

    sp_a0 = _rd("R_BAB60")
    sp_b0 = _rd("R_BAB00")

    q2_8a0 = _rd("R_BA8A0")
    q1_a20 = _rd("R_BAA20")

    b0 = _rd("R_124AAB"); b1 = _rd("R_124ABB")

    v0 = bsub(q2_8a0, b0); v1 = bsub(q1_a20, b1)
    v2 = rot(v0, 6); v3 = rot(v1, 6)
    v1o = bxor(v2, v4s); v2o = bxor(v3, v5s)
    v1o = badd(v1o, imm(0x55)); v2o = badd(v2o, imm(0x55))

    q2_950 = _rd("R_BA950"); q3_b30 = _rd("R_BAB30")

    v1o = bxor(v1o, v4s); v2o = bxor(v2o, v5s)
    v1o = badd(v1o, v4s); v2o = badd(v2o, v5s)
    v1o = bxor(v1o, v4s); v2o = bxor(v2o, v5s)
    v1o = bsub(q2_950, v1o); v0 = bsub(q3_b30, v2o)
    v1o = bxor(v1o, v4s); v0 = bxor(v0, v5s)

    v4sb = sp_a0.copy(); v5sb = sp_b0.copy()

    v2 = rot(v1o, 7); v3 = rot(v0, 7)
    v0f = badd(v2, imm(1)); v1f = badd(v3, imm(1))
    v2 = rot(v0f, 3); v3 = rot(v1f, 3)
    v2 = bsub(imm(0x45), v2); v0t = bsub(imm(0x45), v3)
    v2 = bxor(v2, imm(0x2d)); v0t = bxor(v0t, imm(0x2d))
    v2 = badd(v2, imm(0x3f)); v0t = badd(v0t, imm(0x3f))
    v2 = bxor(v2, imm(0x10)); v0t = bxor(v0t, imm(0x10))
    v1r = badd(v2, v5sb); v0r = badd(v0t, v4sb)
    v2 = rot(v1r, 3); v3 = rot(v0r, 3)
    v2 = bsub(imm(0x40), v2); v3 = bsub(imm(0x40), v3)
    v2 = bxor(v2, imm(0x3b)); v3 = bxor(v3, imm(0x3b))
    v1r = badd(v2, v5sb); v0r = badd(v3, v4sb)

    return (bytes(v1r) + bytes(v0r)).decode('ascii')


def _block5_aes_key() -> str:
    """
    VA 0x1dd9b0..0x1ddbf4 — derives AES KEY #3 (64 ASCII hex chars).
    """
    q18 = _rd("R_BABA0")
    q19 = _rd("R_BABC0")
    q17 = _rd("R_BA7C0")
    q16 = _rd("R_BA5D0")

    q6_b5 = _rd("R_BA840")
    q7_b5 = _rd("R_BABD0")

    b0 = _rd("R_124ACC"); b1 = _rd("R_124ADC")
    b2 = _rd("R_124AEC"); b3 = _rd("R_124AFC")

    v1 = b0.copy(); v2 = b1.copy(); v3 = b2.copy(); v4 = b3.copy()

    v1 = bxor(v1, q19); v2 = bxor(v2, q18)
    v3 = bxor(v3, q16); v4 = bxor(v4, q17)
    v1 = bsub(imm(0x80), v1); v2 = bsub(imm(0x80), v2)
    v3 = bsub(imm(0x80), v3); v0 = bsub(imm(0x80), v4)

    v5b = imm(0x0b)
    v1 = bxor(v1, v5b); v2 = bxor(v2, v5b)
    v3 = bxor(v3, v5b); v0 = bxor(v0, v5b)
    v1 = badd(v1, imm(1)); v2 = badd(v2, imm(1))
    v3 = badd(v3, imm(1)); v0 = badd(v0, imm(1))
    v1 = bxor(v1, imm(0xe2)); v2 = bxor(v2, imm(0xe2))
    v3 = bxor(v3, imm(0xe2)); v0 = bxor(v0, imm(0xe2))
    v1 = badd(v1, imm(0x53)); v2 = badd(v2, imm(0x53))
    v3 = badd(v3, imm(0x53)); v0 = badd(v0, imm(0x53))

    q5_load = _rd("R_BA8B0")
    q4_load = _rd("R_BA5E0")

    v1 = bxor(v1, imm(0xd7)); v2 = bxor(v2, imm(0xd7))
    v3 = bxor(v3, imm(0xd7)); v0 = bxor(v0, imm(0xd7))
    v1 = badd(v1, q5_load); v2 = badd(v2, q6_b5)
    v3 = badd(v3, q4_load); v0 = badd(v0, q7_b5)

    v6_save = q18.copy()
    v1 = bxor(v1, q19); v2 = bxor(v2, q18)
    v3 = bxor(v3, q16); v0 = bxor(v0, q17)
    v1 = badd(v1, imm(0xa1)); v2 = badd(v2, imm(0xa1))
    v3 = badd(v3, imm(0xa1)); v0 = badd(v0, imm(0xa1))
    v1 = bxor(v1, q19); v2 = bxor(v2, q18)
    v3 = bxor(v3, q16); v0 = bxor(v0, q17)
    v1 = badd(v1, q19); v2 = badd(v2, q18)
    v3 = badd(v3, q16); v0 = badd(v0, q17)

    v18_new = q19.copy(); v19_new = v6_save.copy()

    v1 = bxor(v1, q19);      v2 = bxor(v2, v6_save)
    v3 = bxor(v3, q16);      v0 = bxor(v0, q17)

    v5_r = badd(v1, imm(0xd8)); v6_r = badd(v2, imm(0xd8))
    v7_r = badd(v3, imm(0xd8)); v4_r = badd(v0, imm(0xd8))

    def _shl5_ushr1_usra2(orig, tmp):
        shl = (orig.astype(np.uint16) << 5).astype(np.uint8)
        shr = (tmp.astype(np.uint16) >> 1).astype(np.uint8)
        return (shl.astype(np.uint16) + (shr.astype(np.uint16) >> 2)).astype(np.uint8)

    v1 = _shl5_ushr1_usra2(v1, v5_r)
    v2 = _shl5_ushr1_usra2(v2, v6_r)
    v3 = _shl5_ushr1_usra2(v3, v7_r)
    v0 = _shl5_ushr1_usra2(v0, v4_r)

    q4_7e0 = _rd("R_BA7E0"); q6_9d0 = _rd("R_BA9D0")
    q7_970 = _rd("R_BA970"); q4_5f0 = _rd("R_BA5F0")

    v1 = bsub(q4_7e0, v1); v2 = bsub(q6_9d0, v2)
    v3 = bsub(q7_970, v3); v0 = bsub(q4_5f0, v0)

    v1 = bxor(v1, imm(0x71)); v2 = bxor(v2, imm(0x71))
    v3 = bxor(v3, imm(0x71)); v0 = bxor(v0, imm(0x71))
    v1 = badd(v1, imm(0x37)); v2 = badd(v2, imm(0x37))
    v3 = badd(v3, imm(0x37)); v0 = badd(v0, imm(0x37))

    q5_740 = _rd("R_BA740"); q7_750 = _rd("R_BA750")
    q6_760 = _rd("R_BA760"); q5_b40 = _rd("R_BAB40")

    v1 = bxor(v1, q5_740); v2 = bxor(v2, q7_750)
    v3 = bxor(v3, q6_760); v0 = bxor(v0, q5_b40)
    v1 = bsub(imm(0xba), v1); v2 = bsub(imm(0xba), v2)
    v3 = bsub(imm(0xba), v3); v0 = bsub(imm(0xba), v0)

    v1 = bxor(v1, v18_new); v2 = bxor(v2, v19_new)
    v3 = bxor(v3, q16);     v0 = bxor(v0, q17)

    return (bytes(v1) + bytes(v2) + bytes(v3) + bytes(v0)).decode('ascii')


# ---------------------------------------------------------------------------
# Key derivation — public API
# ---------------------------------------------------------------------------

def derive_all_keys() -> dict:
    """
    Run all six NEON SIMD blocks and return a dict with:
        aes_iv1, aes_key1   — round 1 AES-CBC-256
        aes_iv2, aes_key2   — round 2 AES-CBC-256
        aes_iv3, aes_key3   — round 3 AES-CBC-256
    All values are uppercase hex strings (as they appear in the .so ASCII arrays).
    """
    return {
        'aes_iv1':  _block0_aes_iv(),
        'aes_key1': _block1_aes_key(),
        'aes_iv2':  _block2_aes_iv(),
        'aes_key2': _block3_aes_key(),
        'aes_iv3':  _block4_aes_iv(),
        'aes_key3': _block5_aes_key(),
    }


# ---------------------------------------------------------------------------
# Crypto primitives
# ---------------------------------------------------------------------------

def aes_cbc_decrypt(ciphertext_hex: str, key_hex: str, iv_hex: str) -> bytes:
    """AES-CBC-256 decrypt. Inputs are uppercase hex strings."""
    key = unhexlify(key_hex)
    iv  = unhexlify(iv_hex)
    ct  = unhexlify(ciphertext_hex)
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv))
    dec = cipher.decryptor()
    return dec.update(ct) + dec.finalize()


def _parse_rsa_xml(xml_str: str):
    """Parse Chilkat RSA public-key XML. Returns (n, e, key_size_bytes)."""
    root = ET.fromstring(xml_str.strip())
    n = int.from_bytes(base64.b64decode(root.find('Modulus').text), 'big')
    e = int.from_bytes(base64.b64decode(root.find('Exponent').text), 'big')
    key_bytes = (n.bit_length() + 7) // 8
    return n, e, key_bytes


def _rsa_raw(data: bytes, n: int, e: int, ks: int) -> bytes:
    c = int.from_bytes(data, 'big')
    return pow(c, e, n).to_bytes(ks, 'big')


def _strip_pkcs1(data: bytes):
    if len(data) < 11 or data[0] != 0x00 or data[1] not in (0x01, 0x02):
        return None
    for i in range(2, len(data)):
        if data[i] == 0x00:
            return data[i + 1:] if i >= 10 else None
    return None


def rsa_decrypt_multiblock(ct: bytes, n: int, e: int, ks: int) -> bytes | None:
    if len(ct) % ks != 0:
        return None
    result = b''
    for i in range(len(ct) // ks):
        raw = _rsa_raw(ct[i * ks:(i + 1) * ks], n, e, ks)
        plain = _strip_pkcs1(raw)
        if plain is None:
            return None
        result += plain
    return result


def _extract_xml(raw: bytes, tag: str = '<RSAPublicKey>') -> str:
    """Extract XML from AES-decrypted plaintext."""
    try:
        txt = raw.decode('utf-8', errors='replace')
    except Exception:
        txt = raw.decode('latin-1', errors='replace')
    close = '</' + tag.lstrip('<').rstrip('>')
    idx = txt.find(close)
    if idx >= 0:
        return txt[:idx + len(close) + 1]
    return txt.rstrip('\x00')


def _extract_b64(raw: bytes) -> str:
    """Extract base64 string from AES-decrypted plaintext."""
    b64_chars = frozenset(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
    end = 0
    for i, c in enumerate(raw):
        if c in b64_chars:
            end = i + 1
        else:
            break
    return raw[:end].decode('ascii')


# ---------------------------------------------------------------------------
# One full AES+RSA round
# ---------------------------------------------------------------------------

def _aes_rsa_round(ct1_hex: str, ct2_hex: str,
                   aes_key: str, aes_iv: str, label: str):
    """
    Decrypt two hardcoded ciphertexts with AES-CBC-256, then RSA-chain.
    Returns raw decrypted bytes of the inner key blob.

    ct1_hex  -> AES decrypt -> RSA public-key XML
    ct2_hex  -> AES decrypt -> base64(RSA-encrypted blob)
    RSA decrypt blob with key from ct1 -> returns inner RSA key XML / raw bytes
    """
    print(f"  [{label}] AES decrypt ct1 …", flush=True)
    plain1 = aes_cbc_decrypt(ct1_hex, aes_key, aes_iv)
    xml1   = _extract_xml(plain1)
    if '<RSAPublicKey>' not in xml1:
        raise ValueError(f"[{label}] ct1 did not decrypt to RSA XML: {xml1[:120]}")

    print(f"  [{label}] AES decrypt ct2 …", flush=True)
    plain2  = aes_cbc_decrypt(ct2_hex, aes_key, aes_iv)
    b64_str = _extract_b64(plain2)
    blob    = base64.b64decode(b64_str)

    print(f"  [{label}] RSA decrypt blob ({len(blob)} bytes) …", flush=True)
    n, e, ks = _parse_rsa_xml(xml1)
    print(f"           RSA key: {n.bit_length()} bits, key_size={ks}")
    result = rsa_decrypt_multiblock(blob, n, e, ks)
    if result is None:
        raise ValueError(f"[{label}] RSA decrypt failed")

    return result


# ---------------------------------------------------------------------------
# QR buf2 decoder
# ---------------------------------------------------------------------------

def _decode_buf2(buf2: bytes, rsa_key_xml: str) -> bytes:
    """
    Decrypt the 1024-byte buf2 from the QR codes using the final RSA key.
    Returns the decrypted raw bytes.
    """
    n, e, ks = _parse_rsa_xml(rsa_key_xml)
    print(f"  [buf2] RSA key: {n.bit_length()} bits, ks={ks}, len(buf2)={len(buf2)}", flush=True)
    result = rsa_decrypt_multiblock(buf2, n, e, ks)
    if result is None:
        raw = _rsa_raw(buf2[:ks], n, e, ks)
        plain = _strip_pkcs1(raw)
        if plain:
            result = plain
        else:
            raise ValueError("buf2 RSA decrypt failed")
    return result


# ---------------------------------------------------------------------------
# Biographical field parser
# ---------------------------------------------------------------------------

_BIO_FIELDS = [
    "tipo", "cic", "ocr", "curp", "nombre", "apellido1", "apellido2",
    "entidad", "municipio", "seccion", "etnia", "vigencia", "sexo",
    "indiceHuella1", "indiceHuella2", "version", "fechaGeneracion",
    "firmaVerificadora",
]

# Custom 6-bit character encoding the .so emits inside the final blob.
# Spanish alphabet with Ñ inserted after N, then digits, then '/' and '|'.
_CHAR_TABLE = {}
for _i, _ch in enumerate('ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'):
    _CHAR_TABLE[_i + 1] = _ch
for _d in range(10):
    _CHAR_TABLE[28 + _d] = str(_d)
_CHAR_TABLE[40] = '/'
_CHAR_TABLE[57] = '|'

# Hardcoded WebP header table from .rodata @ 0x124b10 (23 entries used).
# Filled into specific positions of the reconstructed WebP container; the rest
# of the header bytes (positions 4,5,16,17,20,21,28) come from the QR data.
_WEBP_HDR_TABLE = bytes.fromhex("52494646000057454250565038200000009d012a600000")


def _strip_pkcs1_any(data: bytes):
    """Strip PKCS#1 v1.5 padding for both type 01 (signature) and type 02 (encryption)."""
    if len(data) < 11 or data[0] != 0x00 or data[1] not in (0x01, 0x02):
        return None
    for i in range(2, len(data)):
        if data[i] == 0x00 and i >= 10:
            return data[i + 1:]
    return None


def _decode_6bit_stream(data: bytes, n_bytes: int) -> bytes:
    """Unpack 6-bit values from the high bits of the first n_bytes input bytes.
    Each input byte contributes 8 bits MSB-first; every 6 collected bits emit one output byte."""
    out = bytearray()
    bit_buf = 0
    bit_count = 0
    for i in range(n_bytes):
        b = data[i]
        for shift in range(7, -1, -1):
            bit_buf = (bit_buf << 1) | ((b >> shift) & 1)
            bit_count += 1
            if bit_count == 6:
                out.append(bit_buf)
                bit_buf = 0
                bit_count = 0
    return bytes(out)


def _reconstruct_webp(input_buf: bytes, image_count: int) -> bytes:
    """Reassemble the WebP image: 23 header bytes from the .rodata table,
    interleaved with payload bytes copied from input_buf."""
    img = bytearray()
    table_idx = 0
    input_idx = 0
    img_total = image_count + 23
    for pos in range(img_total):
        # The .so picks bytes from input at positions {4,5,16,17,20,21,28} and >29;
        # all other positions in 0..29 come from the constant header table.
        if pos > 29 or pos == 28 \
                or (pos & 0x7fffffee) == 4 \
                or (pos & 0x7ffffffe) == 0x10:
            img.append(input_buf[input_idx])
            input_idx += 1
        else:
            img.append(_WEBP_HDR_TABLE[table_idx])
            table_idx += 1
    return bytes(img)


def _decode_final_blob(blob: bytes) -> tuple[dict, bytes, str]:
    """Decode the 1647-byte signed blob produced after both RSA rounds.

    Layout of `blob` (matches the emulator's working buffer):
        [0]                control byte (b0, always 0)
        [b0+2 .. b0+0x42)  ECDSA signature (64 bytes, raw r||s)
        [b0+0x42 .. b0+0x44) u16 BE: number of input bytes used by the text decoder
        [b0+0x44 ..)       packed 6-bit text data, then a length+image-info trailer

    Returns (fields, webp_bytes, raw_text).
    """
    b0 = blob[0]
    text_count = (blob[b0 + 0x42] << 8) | blob[b0 + 0x43]
    data_start = b0 + 0x44

    # Decode encoded text — 6-bit packing
    text_input = blob[data_start: data_start + text_count]
    text_bytes = _decode_6bit_stream(text_input, text_count)

    # The text section is followed by another length-prefixed field (skipped),
    # then a u16 BE 'image data length' starting at offset w25+6.
    post_text_off = data_start + text_count
    field_len = (blob[post_text_off] << 8) | blob[post_text_off + 1]
    w25 = post_text_off + field_len
    image_count = (blob[w25 + 6] << 8) | blob[w25 + 7]
    img_input_start = w25 + 8
    img_input = blob[img_input_start: img_input_start + image_count + 1]

    webp = _reconstruct_webp(img_input, image_count)

    # Decode bio text via the custom char table
    raw_text = ''.join(
        _CHAR_TABLE.get(b, f'[0x{b:02x}]') for b in text_bytes if b != 0
    )
    fields = {}
    for i, val in enumerate(raw_text.split('|')):
        name = _BIO_FIELDS[i] if i < len(_BIO_FIELDS) else f"campo_{i}"
        fields[name] = val
    return fields, webp, raw_text


# ---------------------------------------------------------------------------
# Main pipeline
# ---------------------------------------------------------------------------

def run_full_pipeline(qr_left: bytes, qr_right: bytes):
    """
    Execute the full pipeline using only hardcoded constants + QR data.
    No .so or Unicorn emulation involved.

    Parameters
    ----------
    qr_left  : raw bytes of qr_izquierdo.bin (the LEFT QR scan, 858 bytes)
    qr_right : raw bytes of qr_derecho.bin   (the RIGHT QR scan, 858 bytes)

    Returns
    -------
    (bio_fields: dict, webp_bytes: bytes, raw_text: str)
    """
    t_pipeline_start = time.perf_counter()

    print("\n=== Key derivation (NEON SIMD blocks 0-5) ===")
    t0 = time.perf_counter()
    keys = derive_all_keys()
    for k, v in keys.items():
        print(f"  {k}: {v}")
    print(f"  [SIMD key derivation: {(time.perf_counter() - t0) * 1000:.1f} ms]")

    # ---- QR binary layout ----
    combined = qr_left[2:] + qr_right[2:]
    buf1 = combined[:688]
    buf2 = combined[688:]
    print(f"\n  QR: buf1={len(buf1)} bytes, buf2={len(buf2)} bytes")

    # ---- Round 1: derive RSA key #2 ----
    print("\n=== Round 1: AES+RSA → key #2 ===")
    t0 = time.perf_counter()
    result1 = _aes_rsa_round(
        ct1_hex=_CT["CT_R1_KEY"], ct2_hex=_CT["CT_R1_BLOB"],
        aes_key=keys['aes_key1'], aes_iv=keys['aes_iv1'], label="Round1",
    )
    rsa_xml2 = result1.decode('latin-1', errors='replace').strip('\x00')
    rsa_xml2 = rsa_xml2[:rsa_xml2.find('</RSAPublicKey>') + len('</RSAPublicKey>')]
    n2, e2, ks2 = _parse_rsa_xml(rsa_xml2)
    print(f"  Key #2: {n2.bit_length()} bits  [{(time.perf_counter() - t0) * 1000:.1f} ms]")

    # ---- Round 2: derive RSA key #4 ----
    print("\n=== Round 2: AES+RSA → key #4 ===")
    t0 = time.perf_counter()
    result2 = _aes_rsa_round(
        ct1_hex=_CT["CT_R2_KEY"], ct2_hex=_CT["CT_R2_BLOB"],
        aes_key=keys['aes_key2'], aes_iv=keys['aes_iv2'], label="Round2",
    )
    rsa_xml4 = result2.decode('latin-1', errors='replace').strip('\x00')
    rsa_xml4 = rsa_xml4[:rsa_xml4.find('</RSAPublicKey>') + len('</RSAPublicKey>')]
    n4, e4, ks4 = _parse_rsa_xml(rsa_xml4)
    print(f"  Key #4: {n4.bit_length()} bits  [{(time.perf_counter() - t0) * 1000:.1f} ms]")

    # ---- Stage A: RSA-decrypt buf2 with key #2 → 970-byte intermediate ----
    print("\n=== Stage A: RSA-decrypt buf2 with key #2 ===")
    t0 = time.perf_counter()
    raw = _rsa_raw(buf2, n2, e2, ks2)
    decrypted_buf2 = _strip_pkcs1_any(raw)
    if not decrypted_buf2:
        raise RuntimeError("buf2 RSA-decrypt with key #2 failed")
    print(f"  decrypted_buf2: {len(decrypted_buf2)} bytes  [{(time.perf_counter() - t0) * 1000:.1f} ms]")

    # ---- Stage B: build the 1024-byte stack buffer and verify with key #4 ----
    # The .so concatenates buf1 + decrypted_buf2 (1658 bytes total) and feeds the
    # first 1024 bytes back through RSA-decrypt with key #4 (PKCS#1 type 01 sig).
    print("\n=== Stage B: RSA-verify stack buffer with key #4 ===")
    t0 = time.perf_counter()
    stack_buf = (buf1 + decrypted_buf2)[:1024]
    raw = _rsa_raw(stack_buf, n4, e4, ks4)
    inner = _strip_pkcs1_any(raw)
    if not inner:
        raise RuntimeError("stack buffer RSA-verify with key #4 failed")
    print(f"  inner blob: {len(inner)} bytes (PKCS#1 type {raw[1]})  [{(time.perf_counter() - t0) * 1000:.1f} ms]")

    # ---- Stage C: assemble the working buffer and decode ----
    # Working buffer x25 = inner blob + tail of decrypted_buf2 not already used.
    # The tail is decrypted_buf2[1024 - len(buf1) :] = decrypted_buf2[336:].
    work = inner + decrypted_buf2[1024 - len(buf1):]
    print(f"\n=== Stage C: decode {len(work)}-byte working buffer ===")
    t0 = time.perf_counter()
    fields, webp, raw_text = _decode_final_blob(work)
    print(f"  text: {len(raw_text)} chars, webp: {len(webp)} bytes  [{(time.perf_counter() - t0) * 1000:.1f} ms]")

    print(f"\n  Biographical fields ({len(fields)}):")
    for k, v in fields.items():
        if k == 'firmaVerificadora':
            print(f"    {k}: {v[:60]}…")
        else:
            print(f"    {k}: {v}")

    print(f"\n  [Pipeline total: {(time.perf_counter() - t_pipeline_start) * 1000:.1f} ms]")
    return fields, webp, raw_text


# ---------------------------------------------------------------------------
# QR extraction from credential image
# ---------------------------------------------------------------------------

def extract_qr_codes(image_path: str):
    """Extract the two INE QR payloads from a credential photo.

    Returns (left_bytes, right_bytes) — each 858 bytes with the original
    2-byte header (byte 0 = 0x00, byte 1 = side index 0/1).

    Requires: Pillow, zxing-cpp  (pip install Pillow zxing-cpp)
    Optional: pillow-heif        (pip install pillow-heif)  for HEIC support
    """
    try:
        from PIL import Image
    except ImportError:
        sys.exit("ERROR: pip install Pillow")

    try:
        import pillow_heif
        pillow_heif.register_heif_opener()
    except ImportError:
        pass  # HEIC support is optional

    try:
        import zxingcpp
    except ImportError:
        sys.exit("ERROR: pip install zxing-cpp")

    img = Image.open(image_path)
    print(f"  Image: {img.size[0]}x{img.size[1]} ({img.mode})")

    results = zxingcpp.read_barcodes(img)
    print(f"  Barcodes found: {len(results)}")

    left = right = None
    for r in results:
        raw = bytes(r.bytes)
        if len(raw) != 858 or raw[0] != 0x00:
            continue
        if raw[1] == 0:
            left = raw
            print(f"  QR izquierdo: {len(raw)} bytes")
        elif raw[1] == 1:
            right = raw
            print(f"  QR derecho:   {len(raw)} bytes")

    missing = [s for s, v in [("izquierdo", left), ("derecho", right)] if v is None]
    if missing:
        sys.exit(f"ERROR: missing QR code(s): {', '.join(missing)}")

    return left, right


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    import argparse
    parser = argparse.ArgumentParser(
        description='INE QR Decoder — Pure-Python Pipeline (no .so / no Unicorn)',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=(
            "Examples:\n"
            "  %(prog)s credencial.jpg\n"
            "  %(prog)s --qr-left qr_izq.bin --qr-right qr_der.bin\n"
        ),
    )
    parser.add_argument('image', nargs='?',
                        help='Credential photo (JPG / PNG / HEIC)')
    parser.add_argument('--qr-left',  metavar='FILE',
                        default=os.path.join(OUTPUT_DIR, 'qr_izquierdo.bin'),
                        help='Pre-extracted left QR binary (skips image decode)')
    parser.add_argument('--qr-right', metavar='FILE',
                        default=os.path.join(OUTPUT_DIR, 'qr_derecho.bin'),
                        help='Pre-extracted right QR binary (skips image decode)')
    args = parser.parse_args()

    print('=' * 70)
    print('  INE QR Decoder — Pure-Python Pipeline (no Unicorn / lief / .so)')
    print('=' * 70)

    os.makedirs(OUTPUT_DIR, exist_ok=True)

    t_total_start = time.perf_counter()

    # ── Step 1: get QR payloads ──
    t_step = time.perf_counter()
    if args.image:
        if not os.path.exists(args.image):
            sys.exit(f"ERROR: image not found: {args.image}")
        print(f"\n[1/2] Extracting QR codes from {os.path.basename(args.image)} ...")
        qr_left, qr_right = extract_qr_codes(args.image)
        # cache for reference
        with open(os.path.join(OUTPUT_DIR, 'qr_izquierdo.bin'), 'wb') as f:
            f.write(qr_left)
        with open(os.path.join(OUTPUT_DIR, 'qr_derecho.bin'), 'wb') as f:
            f.write(qr_right)
    else:
        if not os.path.exists(args.qr_left):
            sys.exit(f"ERROR: QR left not found: {args.qr_left}")
        if not os.path.exists(args.qr_right):
            sys.exit(f"ERROR: QR right not found: {args.qr_right}")
        print(f"\n[1/2] Loading pre-extracted QR binaries ...")
        qr_left  = open(args.qr_left,  'rb').read()
        qr_right = open(args.qr_right, 'rb').read()
    t_step1 = time.perf_counter() - t_step

    # ── Step 2: crypto pipeline ──
    print(f"\n[2/2] Running crypto pipeline ...")
    t_step = time.perf_counter()
    bio_fields, webp_bytes, raw_text = run_full_pipeline(qr_left, qr_right)
    t_step2 = time.perf_counter() - t_step

    # ── Save outputs ──
    out_json = os.path.join(OUTPUT_DIR, 'datos_biograficos.json')
    with open(out_json, 'w', encoding='utf-8') as f:
        json.dump(bio_fields, f, indent=2, ensure_ascii=False)
    print(f"\n  Saved: {out_json}")

    out_img = os.path.join(OUTPUT_DIR, 'foto_ine.webp')
    with open(out_img, 'wb') as f:
        f.write(webp_bytes)
    print(f"  Saved: {out_img}")

    out_txt = os.path.join(OUTPUT_DIR, 'texto_biografico.txt')
    with open(out_txt, 'w', encoding='utf-8') as f:
        f.write(raw_text)
    print(f"  Saved: {out_txt}")

    t_total = time.perf_counter() - t_total_start
    print(f"\n  Timing:")
    print(f"    [1/2] QR extraction:   {t_step1 * 1000:>7.1f} ms")
    print(f"    [2/2] Crypto pipeline: {t_step2 * 1000:>7.1f} ms")
    print(f"    Total:                 {t_total * 1000:>7.1f} ms ({t_total:.2f} s)")
    print('\n  Done.')


if __name__ == '__main__':
    main()
